&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Veste subversive&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Veste-Subversive-(Objet).html&quot; title=&quot;Veste subversive&quot;&gt;Veste subversive (veste)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;45 po&lt;/td&gt;&lt;td&gt;0,5 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Veste subversive&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Veste-Subversive-(Objet).html&quot; title=&quot;Veste subversive&quot;&gt;Veste subversive (v&#234;tement)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;90 po&lt;/td&gt;&lt;td&gt;1 kg&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
